package io.github.jaruizes.proposal.business;
import io.github.jaruizes.proposal.domain.exceptions.DomainException; import org.springframework.stereotype.Component; import java.util.regex.Pattern;
@Component public class SlidePlanValidator { private static final Pattern TITLE=Pattern.compile("(?ms)^### Título de slide\\s*\\R([^\\r\\n]+)"); private static final Pattern GENERIC=Pattern.compile("(?i)\\b(cliente|customer|the client|the customer|nuestro cliente|el cliente)\\b"); private static final Pattern SECTION=Pattern.compile("(?m)^# SECTION-\\d+\\s+—\\s+.+$"); public void validate(String md){if(!SECTION.matcher(md).find())throw new DomainException("slides-plan.md must contain SECTION hierarchy");var m=TITLE.matcher(md);int n=0;while(m.find()){n++;var t=m.group(1).trim();if(t.split("\\s+").length>12)throw new DomainException("Slide title exceeds 12 words: "+t);}if(n==0)throw new DomainException("slides-plan.md has no explicit slide titles");if(GENERIC.matcher(md).find())throw new DomainException("Visible slide copy contains forbidden generic cliente/customer wording");}}
